package com.sorenkai.api.model

import com.sorenkai.api.model.Discussion.Kind.COMMENT
import com.sorenkai.api.model.Discussion.Kind.POST
import kotlinx.serialization.Serializable
import kotlin.time.Instant

/**
 * Represents a discussion item in the system, which can be either
 * a top-level post or a comment on another post.
 *
 * @property id Unique identifier for the discussion (generated by [newId]).
 * @property kind Whether this discussion is a [Kind.POST] (top-level thread)
 *                or a [Kind.COMMENT] (reply to another discussion).
 * @property writingSlug Optional slug of a writing that this discussion is linked to.
 *                       Only set for posts that reference published writings.
 * @property parentId Optional identifier of the parent discussion if this is a comment.
 * @property userId The UID of the user who created the discussion.
 * @property body The main text body of the post/comment (1–5000 chars enforced at validation).
 * @property likes Reserved field for tracking the number of likes (not wired yet).
 * @property hashtags List of hashtags automatically extracted from the body text.
 * @property createdAt Timestamp when the discussion was first created.
 * @property updatedAt Timestamp when the discussion was last updated.
 */
@Serializable
data class Discussion(
    val id: String = com.sorenkai.api.util.newId(),
    val kind: Kind,
    val writingSlug: String? = null,
    val parentId: String? = null,
    val userId: String,
    val body: String,
    val likes: Int = 0,
    val hashtags: List<String> = emptyList(),
    val createdAt: Instant = com.sorenkai.api.util.now(),
    val updatedAt: Instant = com.sorenkai.api.util.now()
) {
    /**
     * The type of discussion entry:
     * - [POST]: A top-level post (thread starter).
     * - [COMMENT]: A comment or reply under a post.
     */
    @Serializable
    enum class Kind { POST, COMMENT }
}
